// # FIRST PASS wave 124 lane A1
// Released source: KS/SRC/ks/PhotoFrontEnd.cpp with shared declarations.
class PanelQuad {
public:
    void TurnOn(bool);
};
class Font;
class PhotoWidget {
    char layout[0x40];
public:
    void Init(PanelQuad *, Font *);
};
class FEMenuEntry;
class FEManager {
public:
    Font font_info;
};
class FEMultiMenu {
    char shared_layout[0x40];
protected:
    FEManager *manager;
public:
    FEMenuEntry *entries;
    PanelQuad *GetPointer(const char *);
    void setHigh(FEMenuEntry *);
};
class PhotoSelectMenu : public FEMultiMenu {
private:
    PanelQuad *arrowPQs[2][2];
    PanelQuad *highlightPQs[3];
    PhotoWidget photoWidgets[3];
    void *title;
    int leftArrowIdx, rightArrowIdx;
    float arrowHiTimer;
    int highlightedIdx;
public:
    void Init(void);
};

void PhotoSelectMenu::Init(void)
{
	arrowPQs[0][0] = GetPointer("pp_btn_3_left_off");
	arrowPQs[0][0]->TurnOn(true);
	arrowPQs[0][1] = GetPointer("pp_btn_3_left_on");
	arrowPQs[0][1]->TurnOn(true);
	arrowPQs[1][0] = GetPointer("pp_btn_3_right_off");
	arrowPQs[1][0]->TurnOn(true);
	arrowPQs[1][1] = GetPointer("pp_btn_3_right_on");
	arrowPQs[1][1]->TurnOn(true);

	photoWidgets[0].Init(GetPointer("pp_polaroid_01"), &manager->font_info);
	photoWidgets[1].Init(GetPointer("pp_polaroid_02"), &manager->font_info);
	photoWidgets[2].Init(GetPointer("pp_polaroid_03"), &manager->font_info);

	highlightPQs[0] = GetPointer("pp_hilite_01");
	highlightPQs[0]->TurnOn(true);
	highlightPQs[1] = GetPointer("pp_hilite_02");
	highlightPQs[1]->TurnOn(true);
	highlightPQs[2] = GetPointer("pp_hilite_03");
	highlightPQs[2]->TurnOn(true);

	arrowHiTimer = 0.0f;
	leftArrowIdx = 0;
	rightArrowIdx = 0;

	setHigh(entries);
}
